import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.D7Ov6LBE.js";const h=JSON.parse('{"title":"Diagnóstico & Roadmap de Engenharia","description":"","frontmatter":{},"headers":[],"relativePath":"engenharia/diagnostico-roadmap.md","filePath":"engenharia/diagnostico-roadmap.md","lastUpdated":1786474711000}'),d={name:"engenharia/diagnostico-roadmap.md"};function r(s,a,n,l,c,p){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="diagnostico-roadmap-de-engenharia" tabindex="-1">Diagnóstico &amp; Roadmap de Engenharia <a class="header-anchor" href="#diagnostico-roadmap-de-engenharia" aria-label="Permalink to &quot;Diagnóstico &amp; Roadmap de Engenharia&quot;">​</a></h1><p>Resumo executivo do diagnóstico original (<code>docs/06-diagnostico-e-plano-de-engenharia.md</code>) — o que o protótipo já entrega e o que falta para produção.</p><h2 id="estado-atual-diagnostico" tabindex="-1">Estado atual (diagnóstico) <a class="header-anchor" href="#estado-atual-diagnostico" aria-label="Permalink to &quot;Estado atual (diagnóstico)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimensão</th><th>Situação</th><th>Nota</th></tr></thead><tbody><tr><td><strong>Funcionalidade</strong></td><td>Completa para o ciclo de vendas (pedido → fiscal → sync → export)</td><td>✅</td></tr><tr><td><strong>Offline</strong></td><td>Núcleo sólido (Dexie, outbox, reatividade)</td><td>✅</td></tr><tr><td><strong>Fiscal</strong></td><td>Motor client-side completo (chave 44 dígitos, XML, DANFE, cupom)</td><td>✅</td></tr><tr><td><strong>Segurança</strong></td><td>Auth mock (docs) e PINs em texto plano</td><td>⚠️ migrar</td></tr><tr><td><strong>Integração ERP</strong></td><td>REST simulado; middleware Adapter documentado mas não implementado</td><td>⚠️</td></tr><tr><td><strong>Testes</strong></td><td>Sem suíte automatizada</td><td>⚠️</td></tr></tbody></table><h2 id="roadmap-sugerido-sprints" tabindex="-1">Roadmap sugerido (sprints) <a class="header-anchor" href="#roadmap-sugerido-sprints" aria-label="Permalink to &quot;Roadmap sugerido (sprints)&quot;">​</a></h2><h3 id="sprint-1-—-fundacao-de-seguranca" tabindex="-1">Sprint 1 — Fundação de segurança <a class="header-anchor" href="#sprint-1-—-fundacao-de-seguranca" aria-label="Permalink to &quot;Sprint 1 — Fundação de segurança&quot;">​</a></h3><ul><li>[ ] Supabase Auth + RLS em todas as tabelas (políticas por <code>auth.uid()</code>).</li><li>[ ] Remover senha <code>ampla2026</code> e PINs em texto plano → hash + perfis gerenciados.</li><li>[ ] <code>VITE_SUPABASE_*</code> obrigatórias no build de produção; remover credenciais de localStorage em prod.</li></ul><h3 id="sprint-2-—-integracao-erp-real" tabindex="-1">Sprint 2 — Integração ERP real <a class="header-anchor" href="#sprint-2-—-integracao-erp-real" aria-label="Permalink to &quot;Sprint 2 — Integração ERP real&quot;">​</a></h3><ul><li>[ ] Microserviço middleware Adapter (Node/Go) com os 4 adaptadores (SAP, TOTVS, Senior, Linx).</li><li>[ ] Substituir o REST simulado do <code>ErpSyncCenter</code> pela chamada real.</li><li>[ ] Retry com backoff exponencial + DLQ persistente.</li></ul><h3 id="sprint-3-—-testes-e-ci" tabindex="-1">Sprint 3 — Testes e CI <a class="header-anchor" href="#sprint-3-—-testes-e-ci" aria-label="Permalink to &quot;Sprint 3 — Testes e CI&quot;">​</a></h3><ul><li>[ ] Vitest para <code>formatters.ts</code> e <code>supabaseAndFiscal.ts</code> (chave 44 dígitos, DV módulo 11, XML).</li><li>[ ] Playwright E2E: fluxo completo de venda offline → sync → export.</li><li>[ ] CI (GitHub Actions): lint + test + build.</li></ul><h3 id="sprint-4-—-resiliencia-de-sync" tabindex="-1">Sprint 4 — Resiliência de sync <a class="header-anchor" href="#sprint-4-—-resiliencia-de-sync" aria-label="Permalink to &quot;Sprint 4 — Resiliência de sync&quot;">​</a></h3><ul><li>[ ] Service worker com Background Sync (fila persistente entre sessões).</li><li>[ ] Detecção de conflitos por <code>updated_at</code> (last-write-wins temporal).</li><li>[ ] Delta sync via <code>syncLogs</code>.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./boas-praticas">Boas Práticas</a></li><li><a href="./../docs-legados/06-diagnostico">Docs original 06 — Diagnóstico</a></li><li><a href="./../docs-legados/05-custos-infra">Docs original 05 — Custos &amp; Infra</a></li></ul>',15)])])}const g=e(d,[["render",r]]);export{h as __pageData,g as default};
